class BenchmarkError(RuntimeError):
    """Report an invalid benchmark setup or failed tool invocation."""


@dataclass(frozen=True)
class OptimizationLevel:
    """Map one public optimization target onto each LLVM stage."""

    name: str
    llvm_opt: str
    llc_opt: str

    @property
    def flag(self) -> str:
        """Return the conventional command-line spelling."""

        return f"-{self.name}"


@dataclass(frozen=True)
class SourceRevision:
    """Git identity used to group and reproduce benchmark runs."""

    commit: str
    short_commit: str
    subject: str
    dirty: bool
    directory_name: str


@dataclass(frozen=True)
class Tools:
    """Resolved compiler and object-inspection executables."""

    cross_cc: Path
    clang: Path
    gcc: Path
    opt: Path
    llc: Path
    host_cxx: Path
    llvm_size: Path
    llvm_nm: Path
    llvm_objdump: Path


@dataclass(frozen=True)
class Configuration:
    """Immutable benchmark configuration."""

    source_dir: Path
    output_dir: Path
    tools: Tools
    levels: tuple[OptimizationLevel, ...]
    target: str
    abi: str
    architecture: str
    target_ms: int
    samples: int
    compile_runs: int
    max_relative_mad: float
    source_revision: SourceRevision


@dataclass(frozen=True)
class CommandResult:
    """Captured successful subprocess result."""

    command: tuple[str, ...]
    stdout: str
    stderr: str
    elapsed_ms: float


@dataclass(frozen=True)
class BuildRecord:
    """One compiler/optimization object and its measured build latency."""

    compiler: str
    level: str
    category: str
    object_path: Path
    compile_ms: float
    text_bytes: int
    section_bytes: int
    object_bytes: int


@dataclass(frozen=True)
class RuntimeRecord:
    """One steady-state generated-code timing emitted by the C++ runner."""

    compiler: str
    level: str
    category: str
    kernel: str
    work_units: int
    median_ns: float
    mad_ns: float
    ns_per_unit: float
    checksum: str


@dataclass(frozen=True)
class KernelSpec:
    """One independently scored runtime kernel."""

    name: str
    category: str
    unit: str
    kind: str


