def parse_levels(value: str) -> tuple[OptimizationLevel, ...]:
    """Parse a comma-separated, duplicate-free optimization-level list.

    Args:
        value: Comma-separated level names without leading dashes.

    Returns:
        Ordered optimization descriptors.

    Raises:
        BenchmarkError: If a level is unknown or no levels were supplied.
    """

    names = [item.strip().removeprefix("-") for item in value.split(",")]
    names = [name for name in names if name]
    if not names:
        raise BenchmarkError("at least one optimization level is required")
    unknown = [name for name in names if name not in LEVELS]
    if unknown:
        raise BenchmarkError(f"unknown optimization level(s): {', '.join(unknown)}")
    return tuple(LEVELS[name] for name in dict.fromkeys(names))


def resolve_tool(value: str, description: str) -> Path:
    """Resolve an explicit path or PATH executable.

    Args:
        value: User-supplied path or executable name.
        description: Human-readable tool role for diagnostics.

    Returns:
        Absolute executable path.

    Raises:
        BenchmarkError: If the executable cannot be found.
    """

    supplied = Path(value)
    if supplied.parent != Path(".") or supplied.is_absolute():
        candidate = supplied.expanduser().resolve()
        if candidate.is_file():
            return candidate
    found = shutil.which(value)
    if found is None:
        raise BenchmarkError(f"cannot find {description}: {value}")
    return Path(found).resolve()


def render_template(template: str, replacements: Mapping[str, str]) -> str:
    """Render the deliberately small benchmark template language.

    Args:
        template: Source text containing ``@NAME@`` placeholders.
        replacements: Placeholder names to replacement text.

    Returns:
        Rendered source.

    Raises:
        BenchmarkError: If a placeholder remains unresolved.
    """

    rendered = template
    for name, replacement in replacements.items():
        rendered = rendered.replace(f"@{name}@", replacement)
    unresolved = sorted(set(re.findall(r"@[A-Z_]+@", rendered)))
    if unresolved:
        raise BenchmarkError(f"unresolved template fields: {', '.join(unresolved)}")
    return rendered


def parse_text_size(output: str) -> int:
    """Sum executable text subsections from ``llvm-size --format=sysv``.

    Args:
        output: llvm-size textual output.

    Returns:
        Total number of executable-section bytes.

    Raises:
        BenchmarkError: If no text section is present.
    """

    total = 0
    found = False
    for line in output.splitlines():
        fields = line.split()
        if len(fields) < 2 or not fields[0].startswith(".text"):
            continue
        try:
            total += int(fields[1], 0)
        except ValueError as error:
            raise BenchmarkError(f"invalid llvm-size row: {line}") from error
        found = True
    if not found:
        raise BenchmarkError("llvm-size output contains no .text section")
    return total


def parse_section_size(output: str) -> int:
    """Return ``llvm-size``'s total section footprint.

    Unlike executable text size, this includes read-only constants, unwind
    records, and other emitted sections. Raw object headers and symbol tables
    are represented separately by ``object_bytes``.
    """

    for line in output.splitlines():
        fields = line.split()
        if len(fields) < 2 or fields[0] != "Total":
            continue
        try:
            return int(fields[1], 0)
        except ValueError as error:
            raise BenchmarkError(f"invalid llvm-size total: {line}") from error
    raise BenchmarkError("llvm-size output contains no Total row")


def parse_runtime_csv(output: str) -> list[RuntimeRecord]:
    """Parse and validate the generated-code runner output.

    Args:
        output: CSV emitted by ``runner.cpp``.

    Returns:
        Typed runtime records.

    Raises:
        BenchmarkError: If required columns or numeric values are invalid.
    """

    records: list[RuntimeRecord] = []
    reader = csv.DictReader(io.StringIO(output))
    required = {
        "compiler",
        "level",
        "category",
        "kernel",
        "work_units",
        "median_ns",
        "mad_ns",
        "ns_per_unit",
        "checksum",
    }
    if reader.fieldnames is None or set(reader.fieldnames) != required:
        raise BenchmarkError("runtime runner emitted an unexpected CSV schema")
    try:
        for row in reader:
            records.append(
                RuntimeRecord(
                    compiler=row["compiler"],
                    level=row["level"],
                    category=row["category"],
                    kernel=row["kernel"],
                    work_units=int(row["work_units"]),
                    median_ns=float(row["median_ns"]),
                    mad_ns=float(row["mad_ns"]),
                    ns_per_unit=float(row["ns_per_unit"]),
                    checksum=row["checksum"],
                )
            )
    except (KeyError, TypeError, ValueError) as error:
        raise BenchmarkError("runtime runner emitted an invalid CSV value") from error
    if not records:
        raise BenchmarkError("runtime runner emitted no measurements")
    if any(
        record.work_units <= 0
        or record.median_ns <= 0.0
        or record.mad_ns < 0.0
        or record.ns_per_unit <= 0.0
        for record in records
    ):
        raise BenchmarkError("runtime runner emitted a non-positive measurement")
    return records


def geometric_mean(values: Iterable[float]) -> float:
    """Return the geometric mean of positive ratios."""

    materialized = tuple(values)
    if not materialized or any(value <= 0.0 for value in materialized):
        raise BenchmarkError("geometric mean requires positive values")
    return math.exp(sum(math.log(value) for value in materialized) / len(materialized))


async def run_checked(
    command: Sequence[str | Path], *, cwd: Path | None = None
) -> CommandResult:
    """Run a command with captured diagnostics and elapsed wall time.

    Args:
        command: Executable and arguments.
        cwd: Optional working directory.

    Returns:
        Captured successful result.

    Raises:
        BenchmarkError: If the process cannot start or exits unsuccessfully.
    """

    normalized = tuple(str(item) for item in command)

    def invoke() -> tuple[subprocess.CompletedProcess[str], float]:
        started = time.perf_counter_ns()
        completed = subprocess.run(
            normalized,
            cwd=cwd,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            check=False,
        )
        elapsed_ms = (time.perf_counter_ns() - started) / 1_000_000.0
        return completed, elapsed_ms

    try:
        process, elapsed_ms = await asyncio.to_thread(invoke)
    except OSError as error:
        rendered = " ".join(normalized)
        raise BenchmarkError(f"cannot execute {rendered}: {error}") from error
    if process.returncode != 0:
        rendered = " ".join(normalized)
        raise BenchmarkError(
            f"command failed ({process.returncode}): {rendered}\n"
            f"stdout:\n{process.stdout}\nstderr:\n{process.stderr}"
        )
    return CommandResult(normalized, process.stdout, process.stderr, elapsed_ms)


def write_rendered(
    template_path: Path,
    destination: Path,
    replacements: Mapping[str, str],
) -> None:
    """Render a UTF-8 source template to the build directory."""

    source = template_path.read_text(encoding="utf-8")
    destination.write_text(
        render_template(source, replacements), encoding="utf-8", newline="\n"
    )


def compiler_prefix(compiler: str, level: str) -> str:
    """Return a stable C-compatible link-name prefix."""

    if compiler not in COMPILERS or level not in LEVELS:
        raise BenchmarkError(f"invalid compiler/level pair: {compiler}/{level}")
    identifier = re.sub(r"[^A-Za-z0-9_]", "_", compiler)
    return f"{identifier}_{level}_"


def runner_fragments(
    levels: Sequence[OptimizationLevel],
) -> tuple[str, str, str]:
    """Build C declarations and the C++ variant table for selected levels."""

    declarations: list[str] = []
    variants: list[str] = []
    array_fields = []
    for kind in KIND_ORDER:
        count = sum(kernel.kind == kind for kernel in KERNELS)
        array_fields.append(f"    std::array<{FUNCTION_TYPES[kind]}, {count}> {kind};")
    for level in levels:
        for compiler in COMPILERS:
            prefix = compiler_prefix(compiler, level.name)
            for kernel in KERNELS:
                result, arguments = DECLARATIONS[kernel.kind]
                declarations.append(f"{result} {prefix}{kernel.name}({arguments});")
            function_arrays = []
            for kind in KIND_ORDER:
                members = ", ".join(
                    f"{prefix}{kernel.name}"
                    for kernel in KERNELS
                    if kernel.kind == kind
                )
                function_arrays.append("{" + members + "}")
            variants.append(
                "    {"
                f'"{compiler}", "{level.name}", ' + ", ".join(function_arrays) + "},"
            )
    return (
        "\n".join(declarations),
        "\n".join(array_fields),
        "\n".join(variants),
    )


async def measure_pipeline(pipeline: Callable[[], Awaitable[None]], runs: int) -> float:
    """Warm a compilation pipeline and return median end-to-end milliseconds."""

    await pipeline()
    timings: list[float] = []
    for _ in range(runs):
        started = time.perf_counter_ns()
        await pipeline()
        timings.append((time.perf_counter_ns() - started) / 1_000_000.0)
    return statistics.median(timings)


async def inspect_object(
    config: Configuration, object_path: Path
) -> tuple[int, int, int]:
    """Reject hidden symbols and return text, section, and file sizes."""

    undefined = await run_checked(
        (config.tools.llvm_nm, "--undefined-only", "--format=posix", object_path)
    )
    symbols = [line for line in undefined.stdout.splitlines() if line.strip()]
    if symbols:
        raise BenchmarkError(
            f"{object_path.name} is not standalone; undefined symbols:\n"
            + "\n".join(symbols)
        )
    sized = await run_checked((config.tools.llvm_size, "--format=sysv", object_path))
    disassembly = await run_checked(
        (config.tools.llvm_objdump, "--disassemble", "--no-show-raw-insn", object_path)
    )
    object_path.with_suffix(".disasm").write_text(
        disassembly.stdout, encoding="utf-8", newline="\n"
    )
    return (
        parse_text_size(sized.stdout),
        parse_section_size(sized.stdout),
        object_path.stat().st_size,
    )


async def build_cross_native(
    config: Configuration, level: OptimizationLevel, category: str
) -> BuildRecord:
    """Build one category through Cross's native x86-64 backend."""

    prefix = compiler_prefix("cross", level.name)
    source = config.output_dir / f"cross-{level.name}-{category}.x"
    object_path = config.output_dir / f"cross-{level.name}-{category}.o"
    write_rendered(
        config.source_dir / "kernels" / f"{category}.x.in",
        source,
        {"ABI": config.abi, "PREFIX": prefix},
    )

    async def pipeline() -> None:
        await run_checked(
            (
                config.tools.cross_cc,
                "-c",
                level.flag,
                "-target",
                config.target,
                f"-mabi={config.abi}",
                f"-march={config.architecture}",
                "-fno-unwind-tables",
                "-fno-asynchronous-unwind-tables",
                source,
                "-o",
                object_path,
            )
        )

    compile_ms = await measure_pipeline(pipeline, config.compile_runs)
    sizes = await inspect_object(config, object_path)
    return BuildRecord("cross", level.name, category, object_path, compile_ms, *sizes)


async def build_llc(
    config: Configuration, level: OptimizationLevel, category: str
) -> BuildRecord:
    """Build one category through Cross IR, LLVM optimization, and llc."""

    prefix = compiler_prefix("llc", level.name)
    source = config.output_dir / f"llc-{level.name}-{category}.x"
    input_ir = config.output_dir / f"llc-{level.name}-{category}.ll"
    optimized_ir = config.output_dir / f"llc-{level.name}-{category}.opt.ll"
    object_path = config.output_dir / f"llc-{level.name}-{category}.o"
    write_rendered(
        config.source_dir / "kernels" / f"{category}.x.in",
        source,
        {"ABI": config.abi, "PREFIX": prefix},
    )

    async def pipeline() -> None:
        await run_checked(
            (
                config.tools.cross_cc,
                "-emit-llvm",
                level.flag,
                "-target",
                config.target,
                f"-mabi={config.abi}",
                f"-march={config.architecture}",
                "-fno-unwind-tables",
                "-fno-asynchronous-unwind-tables",
                source,
                "-o",
                input_ir,
            )
        )
        await run_checked(
            (
                config.tools.opt,
                f"-{level.llvm_opt}",
                input_ir,
                "-S",
                "-o",
                optimized_ir,
            )
        )
        await run_checked(
            (
                config.tools.llc,
                f"-{level.llc_opt}",
                "--filetype=obj",
                optimized_ir,
                "-o",
                object_path,
            )
        )

    compile_ms = await measure_pipeline(pipeline, config.compile_runs)
    sizes = await inspect_object(config, object_path)
    return BuildRecord("llc", level.name, category, object_path, compile_ms, *sizes)


def gcc_common_flags(config: Configuration) -> tuple[str, ...]:
    """Return runtime-free GCC flags shared by C and GIMPLE inputs."""

    return (
        "-ffreestanding",
        "-fno-builtin",
        "-fno-stack-protector",
        "-fno-unwind-tables",
        "-fno-asynchronous-unwind-tables",
        "-fno-ident",
        "-ffp-contract=off",
        "-fno-lto",
        f"-march={config.architecture}",
    )


async def build_gcc_bridge(
    config: Configuration,
    level: OptimizationLevel,
    compiler: str,
    category: str,
) -> BuildRecord:
    """Build typed Cross MIR through GCC's GIMPLE or RTL pipeline."""

    if compiler not in {"gcc-gimple", "gcc-rtl"}:
        raise BenchmarkError(f"unsupported GCC bridge: {compiler}")
    prefix = compiler_prefix(compiler, level.name)
    source = config.output_dir / f"{compiler}-{level.name}-{category}.x"
    gimple_source = config.output_dir / f"{compiler}-{level.name}-{category}.gimple.c"
    object_path = config.output_dir / f"{compiler}-{level.name}-{category}.o"
    write_rendered(
        config.source_dir / "kernels" / f"{category}.x.in",
        source,
        {"ABI": config.abi, "PREFIX": prefix},
    )
    emit = "-emit-gimple=rtl" if compiler == "gcc-rtl" else "-emit-gimple"

    async def pipeline() -> None:
        await run_checked(
            (
                config.tools.cross_cc,
                emit,
                level.flag,
                "-target",
                config.target,
                f"-mabi={config.abi}",
                f"-march={config.architecture}",
                "-fno-unwind-tables",
                "-fno-asynchronous-unwind-tables",
                source,
                "-o",
                gimple_source,
            )
        )
        await run_checked(
            (
                config.tools.gcc,
                "-c",
                level.flag,
                "-fgimple",
                *gcc_common_flags(config),
                gimple_source,
                "-o",
                object_path,
            )
        )

    compile_ms = await measure_pipeline(pipeline, config.compile_runs)
    sizes = await inspect_object(config, object_path)
    return BuildRecord(compiler, level.name, category, object_path, compile_ms, *sizes)


async def build_c_compiler(
    config: Configuration,
    level: OptimizationLevel,
    compiler: str,
    category: str,
) -> BuildRecord:
    """Build the equivalent freestanding C corpus with GCC or Clang."""

    if compiler not in {"gcc", "clang"}:
        raise BenchmarkError(f"unsupported C compiler: {compiler}")
    executable = config.tools.gcc if compiler == "gcc" else config.tools.clang
    prefix = compiler_prefix(compiler, level.name)
    source = config.output_dir / f"{compiler}-{level.name}-{category}.c"
    object_path = config.output_dir / f"{compiler}-{level.name}-{category}.o"
    write_rendered(
        config.source_dir / "kernels" / f"{category}.c.in",
        source,
        {"PREFIX": prefix},
    )
    common_flags = (
        "-std=c11",
        *gcc_common_flags(config),
    )

    async def pipeline() -> None:
        await run_checked(
            (
                executable,
                "-c",
                level.flag,
                *common_flags,
                source,
                "-o",
                object_path,
            )
        )

    compile_ms = await measure_pipeline(pipeline, config.compile_runs)
    sizes = await inspect_object(config, object_path)
    return BuildRecord(compiler, level.name, category, object_path, compile_ms, *sizes)


async def build_all(config: Configuration) -> list[BuildRecord]:
    """Build every compiler and optimization-level combination."""

    records: list[BuildRecord] = []
    for level in config.levels:
        print(f"building {level.name} ...", flush=True)
        for unit in BUILD_UNITS:
            records.append(await build_cross_native(config, level, unit))
            records.append(await build_llc(config, level, unit))
            records.append(await build_gcc_bridge(config, level, "gcc-gimple", unit))
            records.append(await build_gcc_bridge(config, level, "gcc-rtl", unit))
            records.append(await build_c_compiler(config, level, "gcc", unit))
            records.append(await build_c_compiler(config, level, "clang", unit))
    return records


async def run_generated_code(
    config: Configuration, builds: Sequence[BuildRecord]
) -> list[RuntimeRecord]:
    """Link all variants into one process and collect calibrated timings."""

    declarations, array_fields, variants = runner_fragments(config.levels)
    runner_source = config.output_dir / "runner.cpp"
    write_rendered(
        config.source_dir / "runner.cpp.in",
        runner_source,
        {
            "DECLARATIONS": declarations,
            "FUNCTION_ARRAYS": array_fields,
            "VARIANTS": variants,
        },
    )
    executable = config.output_dir / (
        "runner.exe" if sys.platform == "win32" else "runner"
    )
    await run_checked(
        (
            config.tools.host_cxx,
            "-std=c++20",
            "-O2",
            "-ffp-contract=off",
            runner_source,
            *(record.object_path for record in builds),
            "-o",
            executable,
        )
    )
    result = await run_checked((executable, str(config.target_ms), str(config.samples)))
    (config.output_dir / "runtime.csv").write_text(
        result.stdout, encoding="utf-8", newline="\n"
    )
    records = parse_runtime_csv(result.stdout)
    expected_count = len(config.levels) * len(COMPILERS) * len(KERNELS)
    if len(records) != expected_count:
        raise BenchmarkError(
            f"runner emitted {len(records)} rows; expected {expected_count}"
        )
    expected_keys = {
        (compiler, level.name, kernel.category, kernel.name)
        for level in config.levels
        for compiler in COMPILERS
        for kernel in KERNELS
    }
    actual_keys = {
        (record.compiler, record.level, record.category, record.kernel)
        for record in records
    }
    if actual_keys != expected_keys:
        missing = sorted(expected_keys - actual_keys)
        unexpected = sorted(actual_keys - expected_keys)
        raise BenchmarkError(
            "runner emitted an invalid measurement key set; "
            f"missing={missing}, unexpected={unexpected}"
        )
    return records


def build_totals(
    builds: Sequence[BuildRecord], compiler: str, level: str
) -> tuple[int, int, int, float]:
    """Sum category objects into one compiler/profile footprint."""

    selected = [
        record
        for record in builds
        if record.compiler == compiler and record.level == level
    ]
    if {record.category for record in selected} != set(BUILD_UNITS):
        raise BenchmarkError(f"incomplete build records for {compiler}/{level}")
    return (
        sum(record.text_bytes for record in selected),
        sum(record.section_bytes for record in selected),
        sum(record.object_bytes for record in selected),
        sum(record.compile_ms for record in selected),
    )


def category_runtime_advantage(
    runtime_index: Mapping[tuple[str, str, str, str], RuntimeRecord],
    compiler: str,
    level: str,
    category: str,
) -> float:
    """Return candidate time / Cross time for one equally weighted category."""

    ratios = []
    for kernel in (item for item in KERNELS if item.category == category):
        cross = runtime_index[("cross", level, category, kernel.name)]
        candidate = runtime_index[(compiler, level, category, kernel.name)]
        ratios.append(candidate.ns_per_unit / cross.ns_per_unit)
    return geometric_mean(ratios)


def balanced_runtime_advantage(
    runtime_index: Mapping[tuple[str, str, str, str], RuntimeRecord],
    compiler: str,
    level: str,
) -> float:
    """Return a category-balanced candidate-time/Cross-time score."""

    return geometric_mean(
        category_runtime_advantage(runtime_index, compiler, level, category)
        for category in CATEGORIES
    )


def leave_one_category_out_runtime_advantage(
    runtime_index: Mapping[tuple[str, str, str, str], RuntimeRecord],
    compiler: str,
    level: str,
) -> float:
    """Return the weakest score after removing any one use-case category."""

    category_scores = {
        category: category_runtime_advantage(runtime_index, compiler, level, category)
        for category in CATEGORIES
    }
    if len(category_scores) < 2:
        return next(iter(category_scores.values()))
    return min(
        geometric_mean(
            score for category, score in category_scores.items() if category != omitted
        )
        for omitted in CATEGORIES
    )


def worst_category_runtime_advantage(
    runtime_index: Mapping[tuple[str, str, str, str], RuntimeRecord],
    compiler: str,
    level: str,
) -> float:
    """Return the weakest individual category ratio."""

    return min(
        category_runtime_advantage(runtime_index, compiler, level, category)
        for category in CATEGORIES
    )


def unstable_runtime_measurements(
    runtime: Sequence[RuntimeRecord], level: str, max_relative_mad: float
) -> list[dict[str, object]]:
    """Describe timings whose median absolute deviation is too large."""

    unstable = []
    for record in runtime:
        if record.level != level:
            continue
        relative_mad = record.mad_ns / record.median_ns
        if relative_mad <= max_relative_mad:
            continue
        unstable.append(
            {
                "compiler": record.compiler,
                "category": record.category,
                "kernel": record.kernel,
                "relative_mad": relative_mad,
            }
        )
    return unstable


def leave_one_unit_out_size_advantage(
    builds: Sequence[BuildRecord],
    compiler: str,
    level: str,
    field: str,
) -> float:
    """Return the weakest additive size ratio after omitting one source unit."""

    if field not in {"text_bytes", "section_bytes"}:
        raise BenchmarkError(f"unsupported size field: {field}")

    def selected_size(record: BuildRecord) -> int:
        return record.text_bytes if field == "text_bytes" else record.section_bytes

    by_key = {
        (record.compiler, record.level, record.category): record for record in builds
    }
    ratios = []
    for omitted in BUILD_UNITS:
        cross_total = sum(
            selected_size(by_key[("cross", level, unit)])
            for unit in BUILD_UNITS
            if unit != omitted
        )
        candidate_total = sum(
            selected_size(by_key[(compiler, level, unit)])
            for unit in BUILD_UNITS
            if unit != omitted
        )
        ratios.append(candidate_total / cross_total)
    return min(ratios)


def benchmark_objectives(
    config: Configuration,
    builds: Sequence[BuildRecord],
    runtime: Sequence[RuntimeRecord],
) -> dict[str, object]:
    """Return machine-readable O3-speed and Oz-size objective results."""

    levels = {level.name for level in config.levels}
    runtime_index = {
        (item.compiler, item.level, item.category, item.kernel): item
        for item in runtime
    }
    result: dict[str, object] = {}
    if "O3" in levels:
        unstable = unstable_runtime_measurements(runtime, "O3", config.max_relative_mad)
        comparisons = {
            compiler: balanced_runtime_advantage(runtime_index, compiler, "O3")
            for compiler in COMPILERS
            if compiler != "cross"
        }
        robust_comparisons = {
            compiler: leave_one_category_out_runtime_advantage(
                runtime_index, compiler, "O3"
            )
            for compiler in COMPILERS
            if compiler != "cross"
        }
        worst_categories = {
            compiler: worst_category_runtime_advantage(runtime_index, compiler, "O3")
            for compiler in COMPILERS
            if compiler != "cross"
        }
        result["speed_O3"] = {
            "pass": not unstable
            and all(value > 1.0 for value in comparisons.values())
            and all(value > 1.0 for value in robust_comparisons.values())
            and all(value >= 0.90 for value in worst_categories.values()),
            "timing_stable": not unstable,
            "max_relative_mad": config.max_relative_mad,
            "unstable_measurements": unstable,
            "candidate_time_over_cross_time": comparisons,
            "leave_one_category_out": robust_comparisons,
            "worst_category": worst_categories,
        }
    if "Oz" in levels:
        cross_text, cross_sections, _, _ = build_totals(builds, "cross", "Oz")
        text_comparisons: dict[str, float] = {}
        section_comparisons: dict[str, float] = {}
        for compiler in COMPILERS:
            if compiler == "cross":
                continue
            text, sections, _, _ = build_totals(builds, compiler, "Oz")
            text_comparisons[compiler] = text / cross_text
            section_comparisons[compiler] = sections / cross_sections
        robust_text = {
            compiler: leave_one_unit_out_size_advantage(
                builds, compiler, "Oz", "text_bytes"
            )
            for compiler in COMPILERS
            if compiler != "cross"
        }
        robust_sections = {
            compiler: leave_one_unit_out_size_advantage(
                builds, compiler, "Oz", "section_bytes"
            )
            for compiler in COMPILERS
            if compiler != "cross"
        }
        result["size_Oz"] = {
            "pass": all(value > 1.0 for value in text_comparisons.values())
            and all(value > 1.0 for value in section_comparisons.values())
            and all(value > 1.0 for value in robust_text.values())
            and all(value > 1.0 for value in robust_sections.values()),
            "candidate_text_over_cross_text": text_comparisons,
            "candidate_sections_over_cross_sections": section_comparisons,
            "leave_one_unit_out_text": robust_text,
            "leave_one_unit_out_sections": robust_sections,
        }
    return result


def markdown_report(
    config: Configuration,
    builds: Sequence[BuildRecord],
    runtime: Sequence[RuntimeRecord],
    versions: Mapping[str, str],
) -> str:
    """Create aggregate, category, and diagnostic benchmark tables."""

    build_index = {(item.compiler, item.level, item.category): item for item in builds}
    runtime_index = {
        (item.compiler, item.level, item.category, item.kernel): item
        for item in runtime
    }
    objectives = benchmark_objectives(config, builds, runtime)
    lines = [
        "# x86-64 compiler comparison",
        "",
        f"Host: `{platform.platform()}`  ",
        f"Source: `{config.source_revision.short_commit}` "
        f"({config.source_revision.subject})"
        f"{' [dirty]' if config.source_revision.dirty else ''}  ",
        f"Target: `{config.target}` / `{config.architecture}`  ",
        f"Samples: median of {config.samples}, calibrated to at least "
        f"{config.target_ms} ms per sample. Each logical sample averages a "
        "forward/reverse candidate pair; the runner pins one available CPU "
        "when the host permits it.",
        "",
        "All advantage columns are candidate/Cross ratios; values above 1 "
        "mean Cross is faster or smaller. Runtime is a geometric mean inside "
        "each category and then across categories, so adding kernels to one "
        "category cannot silently give that category more weight. Robust speed "
        "is the weakest aggregate after omitting any one category. `sections` "
        "includes constants and unwind records; `object` includes file-format "
        "metadata.",
        "",
        "## Aggregate",
        "",
        "| level | compiler | speed advantage | robust speed | text | text advantage | "
        "sections | section advantage | object | object advantage | compile ms |",
        "| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |",
    ]
    for level in config.levels:
        cross_text, cross_sections, cross_object, _ = build_totals(
            builds, "cross", level.name
        )
        for compiler in COMPILERS:
            text_size, section_size, object_size, compile_ms = build_totals(
                builds, compiler, level.name
            )
            lines.append(
                f"| {level.name} | {compiler} | "
                f"{balanced_runtime_advantage(runtime_index, compiler, level.name):.3f}x "
                f"| {leave_one_category_out_runtime_advantage(runtime_index, compiler, level.name):.3f}x "
                f"| {text_size} | {text_size / cross_text:.3f}x | "
                f"{section_size} | {section_size / cross_sections:.3f}x | "
                f"{object_size} | {object_size / cross_object:.3f}x | "
                f"{compile_ms:.2f} |"
            )
    lines.extend(("", "## Objectives", ""))
    if not objectives:
        lines.append(
            "The selected levels do not include the O3 or Oz objective profiles."
        )
    for name, objective in objectives.items():
        assert isinstance(objective, dict)
        status = "PASS" if objective["pass"] else "FAIL"
        lines.append(f"- `{name}`: **{status}**")
        if name == "speed_O3" and not objective["timing_stable"]:
            unstable = objective["unstable_measurements"]
            assert isinstance(unstable, list)
            lines.append(
                f"  - {len(unstable)} timing measurement(s) exceeded the "
                f"{float(objective['max_relative_mad']):.1%} MAD/median limit."
            )

    lines.extend(
        (
            "",
            "## Category diagnostics",
            "",
            "| level | compiler | category | speed advantage |",
            "| --- | --- | --- | ---: |",
        )
    )
    for level in config.levels:
        for compiler in COMPILERS:
            for category in CATEGORIES:
                lines.append(
                    f"| {level.name} | {compiler} | {category} | "
                    f"{category_runtime_advantage(runtime_index, compiler, level.name, category):.3f}x "
                    "|"
                )

    lines.extend(
        (
            "",
            "## Build-unit size diagnostics",
            "",
            "| level | compiler | source unit | text | text advantage | sections | section advantage |",
            "| --- | --- | --- | ---: | ---: | ---: | ---: |",
        )
    )
    for level in config.levels:
        for compiler in COMPILERS:
            for unit in BUILD_UNITS:
                build = build_index[(compiler, level.name, unit)]
                cross_build = build_index[("cross", level.name, unit)]
                lines.append(
                    f"| {level.name} | {compiler} | {unit} | "
                    f"{build.text_bytes} | "
                    f"{build.text_bytes / cross_build.text_bytes:.3f}x | "
                    f"{build.section_bytes} | "
                    f"{build.section_bytes / cross_build.section_bytes:.3f}x |"
                )

    diagnostic_level = (
        "O3" if "O3" in {item.name for item in config.levels} else config.levels[0].name
    )
    lines.extend(
        (
            "",
            f"## Per-kernel runtime diagnostics ({diagnostic_level})",
            "",
            "| category | kernel | compiler | ns/unit | advantage | MAD/median |",
            "| --- | --- | --- | ---: | ---: | ---: |",
        )
    )
    for kernel in KERNELS:
        cross_record = runtime_index[
            ("cross", diagnostic_level, kernel.category, kernel.name)
        ]
        for compiler in COMPILERS:
            record = runtime_index[
                (compiler, diagnostic_level, kernel.category, kernel.name)
            ]
            lines.append(
                f"| {kernel.category} | {kernel.name} | {compiler} | "
                f"{record.ns_per_unit:.4f} | "
                f"{record.ns_per_unit / cross_record.ns_per_unit:.3f}x | "
                f"{record.mad_ns / record.median_ns:.3%} |"
            )

    lines.extend(("", "## Toolchains", ""))
    for name, version in versions.items():
        lines.append(f"- {name}: `{version}`")
    lines.extend(
        (
            "",
            "The `llc` row is Cross LLVM serialization followed by LLVM `opt` "
            "and `llc`. `gcc-gimple` consumes the same optimized typed Cross "
            "MIR as GCC `__GIMPLE (ssa)` and runs GCC's remaining GIMPLE and "
            'RTL passes. `gcc-rtl` uses `startwith("optimized")` to skip '
            "GCC's optimization GIMPLE passes and enter expansion/RTL. GCC's "
            "GIMPLE interface is experimental; emitted bridge sources are "
            "retained with the report. GCC and Clang compile equivalent "
            "freestanding C with built-ins disabled. Every object is rejected "
            "if it contains an undefined symbol. The objective gates describe "
            "this deterministic corpus; "
            "they are evidence against narrow overfitting, not a claim that "
            "one compiler wins every possible program or host.",
            "",
        )
    )
    return "\n".join(lines)


def write_csv_reports(
    output_dir: Path,
    builds: Sequence[BuildRecord],
    runtime: Sequence[RuntimeRecord],
) -> None:
    """Write stable machine-readable build and runtime records."""

    with (output_dir / "build.csv").open("w", encoding="utf-8", newline="") as file:
        writer = csv.DictWriter(
            file,
            fieldnames=tuple(asdict(builds[0]).keys()),
        )
        writer.writeheader()
        for build_record in builds:
            row = asdict(build_record)
            row["object_path"] = str(build_record.object_path)
            writer.writerow(row)
    with (output_dir / "measurements.csv").open(
        "w", encoding="utf-8", newline=""
    ) as file:
        writer = csv.DictWriter(file, fieldnames=tuple(asdict(runtime[0]).keys()))
        writer.writeheader()
        for runtime_record in runtime:
            writer.writerow(asdict(runtime_record))


async def tool_versions(tools: Tools) -> dict[str, str]:
    """Capture concise version identities for the report."""

    result: dict[str, str] = {}
    for name, executable in (
        ("cross", tools.cross_cc),
        ("clang", tools.clang),
        ("gcc", tools.gcc),
        ("opt", tools.opt),
        ("llc", tools.llc),
    ):
        version = await run_checked((executable, "--version"))
        lines = [line.strip() for line in version.stdout.splitlines() if line.strip()]
        result[name] = concise_version(lines)
    return result


async def require_gimple_frontend(gcc: Path) -> None:
    """Fail early when the selected GCC lacks its experimental GIMPLE parser."""

    result = await run_checked((gcc, "-Q", "--help=c"))
    if "-fgimple" not in f"{result.stdout}\n{result.stderr}":
        raise BenchmarkError(f"selected GCC does not advertise -fgimple support: {gcc}")


def concise_version(lines: Sequence[str]) -> str:
    """Choose the informative identity line from a tool's version banner."""

    if not lines:
        return "unknown"
    first = lines[0]
    if first.startswith("LLVM ("):
        return next(
            (line for line in lines[1:] if "version" in line.casefold()),
            first,
        )
    return first


def slugify(value: str, *, limit: int = 56) -> str:
    """Return one stable, readable filesystem component."""

    slug = re.sub(r"[^a-z0-9]+", "-", value.casefold()).strip("-")
    return (slug or "unnamed")[:limit].rstrip("-")


def git_text(repository: Path, *arguments: str) -> str | None:
    """Read one Git value without making Git a benchmark prerequisite."""

    git = shutil.which("git")
    if git is None:
        return None
    process = subprocess.run(
        (git, "-C", str(repository), *arguments),
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
        check=False,
    )
    if process.returncode != 0:
        return None
    return process.stdout.strip()


def discover_source_revision(repository: Path) -> SourceRevision:
    """Resolve the source revision used by a benchmark invocation."""

    commit = git_text(repository, "rev-parse", "HEAD")
    if not commit:
        return SourceRevision(
            commit="unknown",
            short_commit="unknown",
            subject="source",
            dirty=False,
            directory_name="unknown-source",
        )
    short_commit = git_text(repository, "rev-parse", "--short=8", "HEAD")
    subject = git_text(repository, "log", "-1", "--format=%s")
    status = git_text(repository, "status", "--porcelain=v1")
    dirty = bool(status)
    short_commit = short_commit or commit[:8]
    subject = subject or "commit"
    directory_name = f"{short_commit}-{slugify(subject)}"
    if dirty:
        directory_name += "-dirty"
    return SourceRevision(
        commit=commit,
        short_commit=short_commit,
        subject=subject,
        dirty=dirty,
        directory_name=directory_name,
    )


def default_output_directory(
    source_dir: Path,
    revision: SourceRevision,
    levels: Sequence[OptimizationLevel],
    target_ms: int,
    samples: int,
    compile_runs: int,
    *,
    stamp: str | None = None,
    run_name: str | None = None,
) -> Path:
    """Build a commit-addressed output path for one benchmark run."""

    profile = "-".join(level.name for level in levels)
    if run_name:
        leaf = slugify(run_name)
    else:
        stamp = stamp or time.strftime("%Y%m%d-%H%M%S")
        leaf = (
            f"{stamp}-{profile}-{target_ms}ms-"
            f"{samples}samples-{compile_runs}compiles"
        )
    return (
        source_dir.parents[2]
        / "build"
        / "benchmark"
        / "x86_64"
        / revision.directory_name
        / leaf
    )


def sha256_file(path: Path) -> str:
    """Hash one compiler or benchmark input without loading it all at once."""

    digest = hashlib.sha256()
    with path.open("rb") as file:
        for chunk in iter(lambda: file.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def benchmark_corpus_sha256(source_dir: Path) -> str:
    """Hash every source template that defines generated benchmark work."""

    inputs = [
        source_dir / "runner.cpp.in",
        *sorted((source_dir / "kernels").glob("*.in")),
    ]
    digest = hashlib.sha256()
    for path in inputs:
        relative = path.relative_to(source_dir).as_posix().encode("utf-8")
        digest.update(len(relative).to_bytes(4, "little"))
        digest.update(relative)
        digest.update(bytes.fromhex(sha256_file(path)))
    return digest.hexdigest()


def default_cross_cc(source_dir: Path) -> str:
    """Return the repository's conventional built compiler path."""

    suffix = ".exe" if sys.platform == "win32" else ""
    return str(source_dir.parents[2] / "build" / f"cc{suffix}")


def parse_arguments(argv: Sequence[str]) -> argparse.Namespace:
    """Parse the command-line interface."""

    source_dir = Path(__file__).resolve().parent
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--cross-cc", default=default_cross_cc(source_dir))
    parser.add_argument("--clang", default="clang")
    parser.add_argument("--gcc", default="gcc")
    parser.add_argument("--opt", default="opt")
    parser.add_argument("--llc", default="llc")
    parser.add_argument("--host-cxx", default="clang++")
    parser.add_argument("--llvm-size", default="llvm-size")
    parser.add_argument("--llvm-nm", default="llvm-nm")
    parser.add_argument("--llvm-objdump", default="llvm-objdump")
    parser.add_argument(
        "--output",
        type=Path,
        help="exact output directory (default: a commit-addressed run directory)",
    )
    parser.add_argument(
        "--run-name",
        help="readable run-directory name below the current commit",
    )
    parser.add_argument(
        "--levels",
        default="O3,Oz",
        help="comma-separated profiles (default: the speed and size objectives)",
    )
    parser.add_argument("--architecture", default="x86-64-v3")
    parser.add_argument("--target-ms", type=int, default=20)
    parser.add_argument("--samples", type=int, default=7)
    parser.add_argument("--compile-runs", type=int, default=3)
    parser.add_argument(
        "--max-relative-mad",
        type=float,
        default=0.05,
        help="maximum MAD/median accepted by the O3 speed gate (default: 0.05)",
    )
    return parser.parse_args(argv)


def configuration_from_arguments(arguments: argparse.Namespace) -> Configuration:
    """Resolve and validate the host-dependent benchmark configuration."""

    if arguments.output is not None and arguments.run_name is not None:
        raise BenchmarkError("--output and --run-name are mutually exclusive")
    if arguments.target_ms <= 0:
        raise BenchmarkError("--target-ms must be positive")
    if arguments.samples <= 0 or arguments.samples % 2 == 0:
        raise BenchmarkError("--samples must be a positive odd number")
    if arguments.compile_runs <= 0:
        raise BenchmarkError("--compile-runs must be positive")
    if not math.isfinite(arguments.max_relative_mad) or not (
        0.0 < arguments.max_relative_mad < 1.0
    ):
        raise BenchmarkError("--max-relative-mad must be between zero and one")
    source_dir = Path(__file__).resolve().parent
    levels = parse_levels(arguments.levels)
    revision = discover_source_revision(source_dir.parents[1])
    output_dir = (
        arguments.output.resolve()
        if arguments.output is not None
        else default_output_directory(
            source_dir,
            revision,
            levels,
            arguments.target_ms,
            arguments.samples,
            arguments.compile_runs,
            run_name=arguments.run_name,
        )
    )
    windows = sys.platform == "win32"
    tools = Tools(
        cross_cc=resolve_tool(arguments.cross_cc, "Cross compiler"),
        clang=resolve_tool(arguments.clang, "Clang"),
        gcc=resolve_tool(arguments.gcc, "GCC"),
        opt=resolve_tool(arguments.opt, "LLVM optimizer"),
        llc=resolve_tool(arguments.llc, "LLVM code generator"),
        host_cxx=resolve_tool(arguments.host_cxx, "host C++ compiler"),
        llvm_size=resolve_tool(arguments.llvm_size, "llvm-size"),
        llvm_nm=resolve_tool(arguments.llvm_nm, "llvm-nm"),
        llvm_objdump=resolve_tool(arguments.llvm_objdump, "llvm-objdump"),
    )
    return Configuration(
        source_dir=source_dir,
        output_dir=output_dir,
        tools=tools,
        levels=levels,
        target="x86_64-w64-windows-gnu" if windows else "x86_64-unknown-linux-gnu",
        abi="ms_abi" if windows else "sysv_abi",
        architecture=arguments.architecture,
        target_ms=arguments.target_ms,
        samples=arguments.samples,
        compile_runs=arguments.compile_runs,
        max_relative_mad=arguments.max_relative_mad,
        source_revision=revision,
    )


async def async_main(argv: Sequence[str]) -> int:
    """Run the complete benchmark workflow."""

    arguments = parse_arguments(argv)
    config = configuration_from_arguments(arguments)
    config.output_dir.mkdir(parents=True, exist_ok=True)
    versions = await tool_versions(config.tools)
    await require_gimple_frontend(config.tools.gcc)
    (config.output_dir / "metadata.json").write_text(
        json.dumps(
            {
                "host": platform.platform(),
                "generated_at": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
                "source_revision": asdict(config.source_revision),
                "invocation": [sys.executable, str(Path(__file__).resolve()), *argv],
                "cross_compiler_sha256": sha256_file(config.tools.cross_cc),
                "benchmark_corpus_sha256": benchmark_corpus_sha256(config.source_dir),
                "target": config.target,
                "architecture": config.architecture,
                "levels": [level.name for level in config.levels],
                "compilers": list(COMPILERS),
                "pipelines": dict(PIPELINES),
                "build_units": list(BUILD_UNITS),
                "categories": list(CATEGORIES),
                "kernels": [asdict(kernel) for kernel in KERNELS],
                "target_ms": config.target_ms,
                "samples": config.samples,
                "compile_runs": config.compile_runs,
                "max_relative_mad": config.max_relative_mad,
                "tools": versions,
            },
            indent=2,
        )
        + "\n",
        encoding="utf-8",
        newline="\n",
    )
    builds = await build_all(config)
    runtime = await run_generated_code(config, builds)
    write_csv_reports(config.output_dir, builds, runtime)
    (config.output_dir / "objectives.json").write_text(
        json.dumps(benchmark_objectives(config, builds, runtime), indent=2) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    report = markdown_report(config, builds, runtime, versions)
    report_path = config.output_dir / "report.md"
    report_path.write_text(report, encoding="utf-8", newline="\n")
    print(f"\nreport: {report_path}\n")
    print(report)
    return 0


def main() -> int:
    """CLI entry point with concise diagnostics."""

    try:
        return asyncio.run(async_main(sys.argv[1:]))
    except (BenchmarkError, OSError) as error:
        print(f"benchmark: error: {error}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
